3: export const INSPECTION_RESULT_EVENT = "app.inspection.result";
4: 
5: const checkSchema = z.object({
6:   name: z.string().trim().min(1),
7:   status: z.string().trim().min(1),
8:   detail: z.unknown().optional(),
9: });
10: 
11: const inspectionResultSchema = z.object({
12:   target: z.string().trim().min(1).optional(),
13:   checks: z.array(checkSchema),
14: });
15: 
16: export interface InspectionCheckDetail {
17:   code?: string;
18:   message?: string;
19:   durationMs?: number;
20:   raw: Record<string, unknown>;
21: }
22: 
23: export interface InspectionCheckView {
24:   name: string;
25:   status: string;
26:   passed: boolean;
27:   failed: boolean;
28:   detail?: InspectionCheckDetail;
29: }
30: 
31: export interface InspectionResultView {
32:   target?: string;
33:   checks: InspectionCheckView[];
34: }
35: 
36: export type InspectionParseResult =
37:   | { ok: true; value: InspectionResultView }
38:   | { ok: false };
39: 
40: function readString(record: Record<string, unknown>, key: string): string | undefined {
41:   const value = record[key];
42:   return typeof value === "string" && value.trim().length > 0 ? value : undefined;
43: }
44: 
45: function normalizeDetail(detail: unknown): InspectionCheckDetail | undefined {
46:   if (detail === undefined || detail === null) return undefined;
47: 
48:   if (typeof detail === "string") {
49:     return detail.trim().length > 0 ? { message: detail, raw: { message: detail } } : undefined;
50:   }
51: 
52:   if (typeof detail !== "object" || Array.isArray(detail)) {
53:     return { raw: { detail } };
54:   }
55: 
56:   const record = detail as Record<string, unknown>;
57:   const duration = record.duration_ms;
58: 
59:   return {
60:     code: readString(record, "code"),
61:     message: readString(record, "message"),
62:     durationMs: typeof duration === "number" && Number.isFinite(duration) ? duration : undefined,
63:     raw: record,
64:   };
65: }
66: 
67: /**
68:  * Validates the raw CUSTOM event payload carried by `app.inspection.result`.
69:  * Unknown detail fields are preserved so the copied error report stays complete.
70:  */
71: export function parseInspectionResult(data: unknown): InspectionParseResult {
72:   const result = inspectionResultSchema.safeParse(data);
73:   if (!result.success) return { ok: false };
74: 
75:   return {
76:     ok: true,
77:     value: {
78:       target: result.data.target,
79:       checks: result.data.checks.map((check) => {
80:         const normalizedStatus = check.status.trim().toLowerCase();
81:         return {
82:           name: check.name,
83:           status: check.status,
84:           passed: normalizedStatus === "passed",
85:           failed: normalizedStatus === "failed",
86:           detail: normalizeDetail(check.detail),
87:         };
88:       }),
89:     },
90:   };
91: }
